}

const hourRedisDataRaw = {{node:get_cache_node_PlehNpGh.data}};

const hourRedisData =
  hourRedisDataRaw === "" ||
  hourRedisDataRaw === null ||
  hourRedisDataRaw === undefined
    ? []
    : JSON.parse(hourRedisDataRaw);

if(hourRedisData.length === 0) {
  return {
    status: 'Failed',
    message: 'No transaction within this hour.'
  }
} else {
  return {
    status: 'Success',
    message: ''
  }
}

const summaryRedisDataRaw = {{node:get_cache_node_F6MiiP8x.data}};
const hourRedisDataRaw = {{node:get_cache_node_PlehNpGh.data}};
const previousHour = {{node:code_node_X1DJxbjM2.data.one_hour_ago}};
const summaryRedisData =
  summaryRedisDataRaw === "" ||
  summaryRedisDataRaw === null ||
  summaryRedisDataRaw === undefined
    ? { processed_hours: [], items: [] }
    : JSON.parse(summaryRedisDataRaw);
const hourRedisData =
  hourRedisDataRaw === "" ||
  hourRedisDataRaw === null ||
  hourRedisDataRaw === undefined
    ? []
    : JSON.parse(hourRedisDataRaw);
let latestSummaryRedisData = {};

const needCalculate = !(
  Object.keys(summaryRedisData).length > 0 &&
  summaryRedisData.processed_hours &&
  summaryRedisData.processed_hours.find((hours) => hours === previousHour)
);

// Helper function to create composite key
const getCompositeKey = (item) => {
  return `${item.organization_id}|${item.plant_id}|${item.storage_location_id}|${item.item_id}`;
};

// Helper function to aggregate hourRedisData
const aggregateHourData = (data) => {
  if (!data || data.length === 0) return {};

  const aggregatedMap = new Map();

  data.forEach((item) => {
    const key = getCompositeKey(item);
    const quantity = parseFloat(item.quantity) || 0;
    const triggerSource = item.trigger_source;

    if (!aggregatedMap.has(key)) {
      aggregatedMap.set(key, {
        organization_id: item.organization_id,
        plant_id: item.plant_id,
        storage_location_id: item.storage_location_id,
        item_id: item.item_id,
        sales_demand_qty: 0,
        actual_consumption_qty: 0,
        abnormal_flag: 0,
        abnormal_reason: ''
      });
    }

    const entry = aggregatedMap.get(key);

    // Check trigger_source and add to appropriate field
    if (triggerSource === "SO_ISSUED" || triggerSource === "SO_CANCELLED") {
      entry.sales_demand_qty += quantity;
    } else if (
      ["DO_COMPLETED", "PT_ISSUED", "MSI_COMPLETED"].includes(triggerSource)
    ) {
      entry.actual_consumption_qty += quantity;
    }
  });

  return aggregatedMap; // Return Map instead of Object
};

if (needCalculate) {
  // Process hourRedisData if it exists
  let processedHourDataMap = new Map();
  if (hourRedisData && hourRedisData.length > 0) {
    processedHourDataMap = aggregateHourData(hourRedisData);
  }

  // Start with existing summary data
  latestSummaryRedisData = {
    processed_hours: [...(summaryRedisData.processed_hours || [])],
    items: [...(summaryRedisData.items || [])],
  };

  // Create a Map from existing items for easy lookup
  const existingItemsMap = new Map();
  latestSummaryRedisData.items.forEach((item) => {
    const key = getCompositeKey(item);
    existingItemsMap.set(key, item);
  });

  // Merge hour data into summary
  processedHourDataMap.forEach((hourEntry, key) => {
    if (existingItemsMap.has(key)) {
      // Update existing entry
      const existingEntry = existingItemsMap.get(key);
      existingEntry.sales_demand_qty += hourEntry.sales_demand_qty;
      existingEntry.actual_consumption_qty +=
        hourEntry.actual_consumption_qty;
    } else {
      // Add new entry
      existingItemsMap.set(key, { ...hourEntry });
    }
  });

  // Convert Map back to array
  latestSummaryRedisData.items = Array.from(existingItemsMap.values());

  // Update processed_hours
  if (!latestSummaryRedisData.processed_hours.includes(previousHour)) {
    latestSummaryRedisData.processed_hours.push(previousHour);
  }

  return {
    latestSummaryRedisData,
  };
} else {
  return {
    latestSummaryRedisData: summaryRedisData,
  };
}

