const organizationID = {{workflowparams:organization_id}};
const plantData = {{node:search_node_xc43Yk1f.data.data}} || [];
const reorderConfig = {{node:get_node_lx8BhzFr.data.data}};

if(reorderConfig.mrp_level === 'By Plant') {
  const plantIDList = plantData.map(plant => plant.id) || [];
  return { deptIDList: plantIDList }
} else if (reorderConfig.mrp_level === 'By Organization') {
  return { deptIDList: [organizationID] }
}

const deptID = {{node:loop_l6wx6B3F}}; // This can be either organization_id or plant_id
const balanceData = {{node:search_node_be4AYvbU.data.data}};
const onOrderPOData = {{node:search_node_gnzEqmQw.data.data}};
const soOutstandingData = {{node:search_node_2zY1Njyc.data.data}};
const reorderConfig = {{node:get_node_lx8BhzFr.data.data}};
const itemData = {{node:loop_GvW0LO0l}};

// Helper function to filter data by the department ID (either organization_id or plant_id)
const filterByDept = (data, config, deptID) => {
  if (!data || data.length === 0) return [];

  const mrpLevel = config?.mrp_level;

  if (mrpLevel === "By Organization") {
    // Filter by organization_id
    return data.filter((item) => item.organization_id === deptID);
  } else if (mrpLevel === "By Plant") {
    // Filter by plant_id
    return data.filter((item) => item.plant_id === deptID);
  }

  return [];
};

// Helper function to sum values from filtered data
const sumField = (data, field) => {
  if (!data || data.length === 0) return 0;
  return data.reduce(
    (total, item) => total + (parseFloat(item[field]) || 0),
    0,
  );
};

// Helper function to get conversion rate from alt_uom_id to base_uom
const getConversionRate = (uomConversions, altUomId) => {
  if (
    !uomConversions ||
    !Array.isArray(uomConversions) ||
    uomConversions.length === 0
  ) {
    return 1; // Default to 1 if no conversion found
  }

  // Find the conversion for the given alt_uom_id
  const conversion = uomConversions.find(
    (conv) => conv.alt_uom_id === altUomId,
  );

  if (conversion) {
    return conversion.base_qty;
  }

  return 1; // Default to 1 if no conversion found
};

// Filter data based on reorder config level using the mapped deptID
const balanceDataFiltered = filterByDept(balanceData, reorderConfig, deptID);
const onOrderPODataFiltered = filterByDept(
  onOrderPOData,
  reorderConfig,
  deptID,
);
const soOutstandingDataFiltered = filterByDept(
  soOutstandingData,
  reorderConfig,
  deptID,
);

// Calculate totals based on filtered data
const unrestrictedQty = sumField(balanceDataFiltered, "unrestricted_qty");
const qualityinspQty = sumField(balanceDataFiltered, "qualityinsp_qty");
const intransitQty = sumField(balanceDataFiltered, "intransit_qty");
const openQty = sumField(onOrderPODataFiltered, "open_qty");

// Calculate SO outstanding quantity with UOM conversion
const uomConversions = itemData?.table_uom_conversion || [];
let totalOutstandingInBaseUOM = 0;

if (soOutstandingDataFiltered && soOutstandingDataFiltered.length > 0) {
  soOutstandingDataFiltered.forEach((soItem) => {
    const outstandingQty = parseFloat(soItem.outstanding_quantity) || 0;
    const soUom = soItem.so_item_uom;

    if (soUom) {
      // Get conversion rate from SO UOM to base UOM
      const conversionRate = getConversionRate(uomConversions, soUom);
      // Convert to base UOM
      const convertedQty = outstandingQty * conversionRate;
      totalOutstandingInBaseUOM += convertedQty;
    } else {
      // If no UOM specified, assume it's already in base UOM
      totalOutstandingInBaseUOM += outstandingQty;
    }
  });
}

// Calculate available stock
const availableStock =
  unrestrictedQty +
  qualityinspQty +
  (intransitQty + openQty) -
  totalOutstandingInBaseUOM;

// Format to 3 decimal places
const formattedAvailableStock = Math.round(availableStock * 1000) / 1000;

return {
  available_stock: formattedAvailableStock,
};

const reorderSupplier = {{node:loop_GvW0LO0l.table_reorder_supplier}} || [];
let selectedSupplier = null;

// Check if reorderSupplier is empty
if (reorderSupplier.length === 0) {
  return {
    supplier: null,
    message: "No suppliers configured.",
    has_supplier: 'No'
  };
}

// Filter active suppliers
const activeSuppliers = reorderSupplier.filter(supplier => supplier.active === 1);

if (activeSuppliers.length === 0) {
  return {
    supplier: null,
    message: "No active suppliers found.",
    has_supplier: 'No'
  };
}

// Find supplier with the smallest supplier_level (highest priority)
selectedSupplier = activeSuppliers.reduce((min, supplier) => 
  supplier.supplier_level < min.supplier_level ? supplier : min
);

// Return supplier data only
return {
  supplier: selectedSupplier,
  has_supplier: 'Yes',
  message: "Supplier found successfully."
};

const availableStock = parseFloat({{node:code_node_kqZAAWbi.data.available_stock}} || 0);
const reorderConfig = {{node:get_node_lx8BhzFr.data.data}};
