const availableStock = parseFloat({{node:code_node_kqZAAWbi.data.available_stock}} || 0);
const reorderConfig = {{node:get_node_lx8BhzFr.data.data}};
let suggestedStock = 0;

const maxStockQty = parseFloat(reorderConfig?.max_stock_qty) || 0;
suggestedStock = Math.max(0, maxStockQty - availableStock);

return {
  suggested_stock: suggestedStock
};

const pastSummaryList = {{node:sql_node_jb8h7s93.data}};
const todaySummaryRaw = {{node:get_cache_node_LjCr5tpM.data}} || '';
const todaySummary = todaySummaryRaw && todaySummaryRaw !== '' ? JSON.parse(todaySummaryRaw) : []
const reorderConfig = {{node:get_node_lx8BhzFr.data.data}};
const availableStock = parseFloat({{node:code_node_kqZAAWbi.data.available_stock}} || 0);
const deptID = {{node:loop_l6wx6B3F}};
const supplierData = {{node:code_node_a11930AV.data.supplier}} || {};
const itemData = {{node:loop_GvW0LO0l}}; // Current item data for filtering
// Helper function to filter by MRP level
const filterByMrpLevel = (data, reorderConfig, deptID) => {
  if (!data || data.length === 0) return [];

  const mrpLevel = reorderConfig?.mrp_level;

  if (mrpLevel === "By Organization") {
    return data.filter((item) => item.organization_id === deptID);
  } else if (mrpLevel === "By Plant") {
    return data.filter((item) => item.plant_id === deptID);
  }

  return data;
};

// Helper function to filter by material/item ID
const filterByMaterial = (data, materialId) => {
  if (!data || data.length === 0) return [];
  return data.filter((item) => item.item_id === materialId);
};

// Helper function to sum field
const sumField = (data, field) => {
  if (!data || data.length === 0) return 0;
  return data.reduce(
    (total, item) => total + (parseFloat(item[field]) || 0),
    0,
  );
};

// Helper function to get unique dates
const getUniqueDates = (data) => {
  if (!data || data.length === 0) return [];
  const dateSet = new Set();
  data.forEach((item) => {
    if (item.summary_date) {
      dateSet.add(item.summary_date);
    }
  });
  return Array.from(dateSet);
};

// STEP 1: Filter out exclude_from_dynamic = 1
const filteredPastSummary = pastSummaryList.filter(
  (item) => item.exclude_from_dynamic !== 1,
);

// STEP 2: Filter by MRP level
const filteredPastByLevel = filterByMrpLevel(
  filteredPastSummary,
  reorderConfig,
  deptID,
);

// STEP 2b: Filter by current material/item
const itemId = itemData?.id;
const pastSummaryByItem = filterByMaterial(filteredPastByLevel, itemId);

// Convert todaySummary to array if it's an object and filter by material
let todaySummaryArray = [];
let todaySummaryByItem = [];
if (todaySummary && todaySummary.items && todaySummary.items.length > 0) {
  todaySummaryArray = filterByMrpLevel(
    todaySummary.items,
    reorderConfig,
    deptID,
  );
  // Filter today summary by current material
  todaySummaryByItem = filterByMaterial(todaySummaryArray, itemId);
}

// STEP 3: Calculate sales demand and actual consumption (filtered by item)
const totalSalesDemand =
  sumField(pastSummaryByItem, "sales_demand_qty") +
  sumField(todaySummaryByItem, "sales_demand_qty");
const totalActualConsumption =
  sumField(pastSummaryByItem, "actual_consumption_qty") +
  sumField(todaySummaryByItem, "actual_consumption_qty");

// STEP 4: Calculate effective days (filtered by item)
const pastExcludeFromDynamic = pastSummaryList.filter(
  (item) => item.exclude_from_dynamic === 1,
);
const pastExcludeByItem = filterByMaterial(pastExcludeFromDynamic, itemId);
const uniqueExcludePastDates = getUniqueDates(pastExcludeByItem);

const usageWindowDays = parseInt(reorderConfig?.usage_window_days) || 0;
const excludedDaysCount = uniqueExcludePastDates.length;
const effectiveDays = usageWindowDays - excludedDaysCount;

// STEP 5: Calculate daily averages
const salesDemandDaily =
  effectiveDays > 0 ? totalSalesDemand / effectiveDays : 0;
const actualConsumptionDaily =
  effectiveDays > 0 ? totalActualConsumption / effectiveDays : 0;

// STEP 6: Dynamic daily demand = max(sales demand daily, actual consumption daily)
const dynamicDailyDemand = Math.max(salesDemandDaily, actualConsumptionDaily);

// STEP 7: Get supplier lead time (from supplier)
const supplierLeadTime = parseFloat(supplierData?.lead_time_days) || 0;
const safetyStock = parseFloat(reorderConfig?.safety_stock_qty) || 0;

// STEP 8: Calculate dynamic target inventory
const dynamicTargetInventory =
  dynamicDailyDemand * supplierLeadTime + safetyStock;

// STEP 9: Calculate suggested replenishment quantity
const suggestedStock = Math.max(0, dynamicTargetInventory - availableStock);

// STEP 10: Check for abnormal sales demand in today's summary
// If today's sales demand > 3x total past sales demand, mark as abnormal

const totalPastSalesDemand = sumField(pastSummaryByItem, "sales_demand_qty");
const totalTodaySalesDemand = sumField(todaySummaryByItem, "sales_demand_qty");
const totalPastActualConsumption = sumField(
  pastSummaryByItem,
  "actual_consumption_qty",
);
const totalTodayActualConsumption = sumField(
  todaySummaryByItem,
  "actual_consumption_qty",
);

let latestTodaySummary = [];
let abnormalFlagCount = 0;
let abnormalReason = "";
if (totalTodaySalesDemand > 3 * totalPastSalesDemand) {
  abnormalFlagCount = 1;
  abnormalReason = "Sales demand is 3x higher than past sales demand";
} else if (totalTodayActualConsumption > 3 * totalPastActualConsumption) {
  abnormalFlagCount = 1;
  abnormalReason =
    "Actual consumption is 3x higher than past actual consumption";
}

const todayItems = todaySummary?.items || [];
latestTodaySummary = todayItems.map((item) => {
  return {
    ...item,
    abnormal_flag:
      item.item_id === itemId ? abnormalFlagCount : item.abnormal_flag,
    abnormal_reason:
      item.item_id === itemId ? abnormalReason : item.abnormal_reason,
  };
});

// Format to 3 decimal places
const formattedSuggestedStock = Math.round(suggestedStock * 1000) / 1000;
const formattedDynamicDailyDemand =
  Math.round(dynamicDailyDemand * 1000) / 1000;
const formattedDynamicTargetInventory =
  Math.round(dynamicTargetInventory * 1000) / 1000;

return {
  suggested_stock: formattedSuggestedStock,
  dynamic_daily_demand: formattedDynamicDailyDemand,
  dynamic_target_inventory: formattedDynamicTargetInventory,
  today_summary: latestTodaySummary,
  abnormal_flag: abnormalFlagCount,
  abnormal_reason: abnormalReason
};

const reorderMethod = {{node:get_node_lx8BhzFr.data.data.reorder_method}};

if(reorderMethod === 'Fixed') {
  return {
    createPR: {{node:code_node_3F3PwM8W.data.create_pr}}
  }
} else {
  return {
    createPR: "Yes"
  }
}

