    abnormal_reason: {{node:code_node_p5MkOw90.data.abnormal_reason}},
    dept_id: deptID
  }
}

return {
  message: 'Suggested stock 0.'
}

const suggestedStock = {{node:code_node_0fuejsDC.data.suggest_stock}} || 0;
const supplierData = {{node:code_node_a11930AV.data.supplier}} || {};
const itemData = {{node:loop_GvW0LO0l}};
const dailyDemandQty = {{node:code_node_0fuejsDC.data.daily_demand_qty}} || 0;
const availableQty = {{node:code_node_0fuejsDC.data.available_qty}} || 0;
const tableUOMConversion = itemData.table_uom_conversion;
let orderUOM = "";
const getConversionRate = (uomConversions, altUomId) => {
  if (
    !uomConversions ||
    !Array.isArray(uomConversions) ||
    uomConversions.length === 0
  ) {
    return 1; // Default to 1 if no conversion found
  }

  // Find the conversion for the given alt_uom_id
  const conversion = uomConversions.find(
    (conv) => conv.alt_uom_id === altUomId,
  );

  if (conversion) {
    return conversion.base_qty;
  }

  return 1; // Default to 1 if no conversion found
};

if (supplierData?.reorder_uom) {
  orderUOM = supplierData.reorder_uom;
} else {
  const purchaseDefaultUOM =
    tableUOMConversion.find((uom) => uom.purchase_default_uom === 1) || null;

  if (purchaseDefaultUOM) {
    orderUOM = purchaseDefaultUOM.alt_uom_id;
  } else {
    orderUOM = itemData.based_uom;
  }
}
// Get Order UOM
const conversionRate = getConversionRate(
  itemData.table_uom_conversion,
  orderUOM,
);

const convertedSuggestedStock = suggestedStock / conversionRate;
const convertedDailyDemand = dailyDemandQty / conversionRate;
const convertedAvailable = availableQty / conversionRate;
// Get MOQ from supplier
const moq = parseFloat(supplierData?.moq_qty) || 0;

// Replenishment quantity = max(MOQ, suggested stock)
const prQty = Math.max(moq, convertedSuggestedStock);

// Format to 3 decimal places
const formattedprQty = Math.round(prQty * 1000) / 1000;

return {
  pr_qty: formattedprQty,
  pr_uom: orderUOM,
  converted_daily_demand: convertedDailyDemand,
  converted_available: convertedAvailable,
};

